// the core never imports a concrete Clock, RNG, Network, or Storage —
// only the port (interface) each one is defined by
interface Clock   { now() -> Time }
interface Random  { next() -> f64 }
interface Network { send(peer, msg); recv() -> Msg }
interface Storage { write(key, val); read(key) -> val }

// two adapters per port, wired in at startup, never inside the core
production := App(RealClock(), OsRandom(),  TcpNetwork(), DiskStorage())
simulation := App(SimClock(),  SeededRandom(seed), SimNetwork(seed), SimStorage(seed))

ready = seeded_shuffle(runnable_coroutines)   // order drawn from the seed, not FIFO
for task in ready:
  task.resume()                 // runs only until its next await/wait()
  // resuming may push new timer/network/disk events onto the event queue below

loop:
  event = event_queue.pop_min() // earliest timestamp wins
  clock = event.timestamp       // jump, don't sleep
  effects = handlers[event.kind](state, event)
  for e in effects: event_queue.push(e)

// FDB Sim2, paraphrased: a 'connection' is two in-memory buffers plus a clogging check
function deliver(conn, packet):
  if clogging.disconnected(conn.from, conn.to):
    return                       // dropped: this is what a partition IS here
  delay = rng.next_delay()       // seeded latency
  schedule_at(clock + delay, () => conn.to.inbox.push(packet))
